// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Do something that affects state but not paused status (e.g., add an empty queue)
        address[] memory emptyQueue = new address[](0);
        c.addNodeDelegatorContractToQueue(emptyQueue);

        // Pause the contract
        // To call pause() we need LRT_MANAGER role. In setUp the deployer has it? 
        // The constructor doesn't set roles, so we assume the test caller is the admin/manager.
        // For simplicity, we directly call pause() which requires onlyLRTManager.
        // Since we can't set roles easily, we'll use vm.prank with the contract owner (the test contract).
        // But the contract's lrtConfig is not set; we need to mock an LRTConfig.
        // However, the requirement says to interact ONLY through c, but we can use vm.prank to simulate the caller.
        // To avoid complexity, we'll just test the paused() function behavior after initializing.
        // The reference: paused() returns false; the mutant: paused() returns true.
        // We don't need to call pause() — just check the default state.

        bool isPaused = c.paused();
        // The reference contract should have paused() returning false after initialization.
        // The mutant returns !_paused, which is true (since _paused is false initially).
        assertTrue(!isPaused, "paused() should return false initially");
    }
}

