pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address lrtConfigAddr, address[] calldata nodeDelegatorContracts) public {
        // Restrict: lrtConfigAddr must be non-zero and nodeDelegatorContracts must have at least one item
        vm.assume(lrtConfigAddr != address(0));
        vm.assume(nodeDelegatorContracts.length > 0 && nodeDelegatorContracts.length <= 10);
        for (uint256 i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }

        // Initialize the contract and set up lrtConfig via an admin
        vm.startPrank(address(0x1)); // use a non-zero address as admin
        c.initialize(lrtConfigAddr);
        vm.stopPrank();

        // Capture the initial lrtConfig value. It is stored in a public state variable (from LRTConfigRoleChecker)
        address initialConfig;
        // lrtConfig is public, so we can read it via c.lrtConfig()
        // But note: after initialize, we cannot change it without admin. The bug makes updateLRTConfig do nothing.
        // We'll read it before and after addNodeDelegatorContractToQueue.
        initialConfig = address(c.lrtConfig());

        // Perform the call to addNodeDelegatorContractToQueue as an admin (the reference allows only LRT admin)
        vm.prank(address(0x1)); // admin
        c.addNodeDelegatorContractToQueue(nodeDelegatorContracts);

        // The general rule: after adding node delegators, lrtConfig remains unchanged.
        address finalConfig = address(c.lrtConfig());
        assertTrue(initialConfig == finalConfig, "lrtConfig should not change when adding node delegators");
    }
}

