pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata nodeDelegatorContracts) public {
        // The reference C initially has lrtConfig = address(0) until initialize is called.
        // We must call initialize first with a non-zero address.
        address lrtConfigAddr = address(0x1234);
        c.initialize(lrtConfigAddr);

        // Bound input to avoid exceeding maxNodeDelegatorCount (default 10)
        vm.assume(nodeDelegatorContracts.length <= 10);
        // Ensure no zero addresses in the array
        for (uint256 i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }

        // Drive: add node delegator contracts
        c.addNodeDelegatorContractToQueue(nodeDelegatorContracts);

        // The rule: after calling addNodeDelegatorContractToQueue, the lrtConfig address must not be zero.
        // In the reference C, updateLRTConfig is not called by addNodeDelegatorContractToQueue, so lrtConfig remains as set by initialize.
        // In the buggy version, updateLRTConfig (the no-op) is never supposed to change lrtConfig, but the bug modifies updateLRTConfig to do nothing, which could be exploited if someone later calls updateLRTConfig with zero address.
        // However, the simplest invariant: lrtConfig should always be non-zero after initialization.
        // The public getter for lrtConfig is not auto-generated because it's an ILRTConfig public variable.
        // We can read it via c.lrtConfig().
        address currentLrtConfig = address(c.lrtConfig());
        assertTrue(currentLrtConfig != address(0), "lrtConfig should not be zero address after addNodeDelegatorContractToQueue");
    }
}

