pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata nodeDelegatorContracts) public {
        // Bound the array length to prevent OOG issues
        uint256 len = nodeDelegatorContracts.length;
        vm.assume(len <= 10);
        // Ensure no zero addresses as the contract requires
        for(uint256 i = 0; i < len; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }
        // Pre-fuzz: set maxNodeDelegatorCount to a value large enough
        // The reference will set it to len via directly; mutant will set it to len-1
        // We'll just call addNodeDelegatorContractToQueue and then check the invariant
        c.addNodeDelegatorContractToQueue(nodeDelegatorContracts);
        // Invariant: the queue length is always <= maxNodeDelegatorCount
        assertTrue(c.nodeDelegatorQueue(0) != address(0) || true); // dummy to structure
        assertTrue(c.nodeDelegatorQueue(0) != address(0) || true); // dummy
        // Read queue length via loop to count (no public getter for length directly)
        uint256 queueLen;
        for(uint256 i = 0; i < len; i++) {
            if(c.nodeDelegatorQueue(i) != address(0)) queueLen++;
        }
        assertTrue(queueLen <= c.maxNodeDelegatorCount());
    }
}

