pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 count, address[] memory nodeDelegators) public {
        // Restrict count to a reasonable range and ensure nodeDelegators is not empty
        count = bound(count, 0, 10);
        vm.assume(nodeDelegators.length > 0);

        // Get the initial maxNodeDelegatorCount (default is 10)
        uint256 initialMax = c.maxNodeDelegatorCount();

        // Update maxNodeDelegatorCount to a value that can accommodate the new delegators
        c.updateMaxNodeDelegatorCount(count);

        // Get the new maxNodeDelegatorCount after update
        uint256 newMax = c.maxNodeDelegatorCount();

        // Add the node delegators (will revert if count is too small, but that's fine)
        // We only care about the case where the addition succeeds
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.addNodeDelegatorContractToQueue.selector, nodeDelegators));

        // If the addition succeeded, the maxNodeDelegatorCount must be at least the number of added delegators
        // Note: The update sets maxNodeDelegatorCount to count (reference) or count-1 (mutant)
        // But since we are testing a general rule, we check that the max is never less than the queue length after success
        if (success) {
            assertTrue(c.maxNodeDelegatorCount() >= nodeDelegators.length);
        }
    }
}

