contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTime, address[] memory delegates) public {
        // Restrict fuzz inputs: warpTime is unused but must be valid, delegates must be non-zero addresses and not too long
        vm.assume(delegates.length <= 10);
        for (uint i = 0; i < delegates.length; i++) {
            vm.assume(delegates[i] != address(0));
        }

        // Record initial maxNodeDelegatorCount (initialized to 10)
        uint256 initialMax = c.maxNodeDelegatorCount();

        // Call addNodeDelegatorContractToQueue; may revert if length exceeds maxNodeDelegatorCount
        // We call it only if the queue length after addition would not exceed maxNodeDelegatorCount
        uint256 currentQueueLen = c.nodeDelegatorQueue().length;
        vm.assume(currentQueueLen + delegates.length <= initialMax);

        // If delegates is empty, the call is still valid (adds nothing) and the assertion should hold
        c.addNodeDelegatorContractToQueue(delegates);

        // After the call, maxNodeDelegatorCount must not have decreased
        uint256 finalMax = c.maxNodeDelegatorCount();
        assertTrue(finalMax >= initialMax);
    }
}

